/**
 * Every test is watched from its first step (BaseTest starts this; no test has to): console errors,
 * failed requests, and a Playwright trace. When a test fails, all of it is saved to
 * {@code target/failures/<TestClass>/<test>/}:
 * <pre>
 * screenshot.png   the page at the moment it failed, full length
 * page.html        the DOM at that moment
 * trace.zip        every step with the page before and after it, network, console:
 *                  open it at https://trace.playwright.dev
 * console.txt      console errors and warnings, and uncaught page errors
 * network.txt      requests that failed or answered 400 or more
 * steps.txt        the steps in plain English, the failed one last, the error, the URL and title
 * run.txt          where and how it ran: site, browser, headless or not, time
 * </pre>
 * Saving never hides the failure: whatever cannot be saved is skipped. A passed test keeps nothing
 * ({@code -Dtrace=always} keeps its trace in target/traces/; {@code -Dtrace=off} traces nothing).
 * <p>
 * Each run starts clean: the run before moves to {@code target/failures-previous/} (so rerunning one
 * test does not lose the rest of a full run's evidence), anything older is deleted, and so are the
 * traces an earlier run kept.
 */
public final class Evidence {
    /** Where failed tests leave their evidence. */
    public static final Path FAILURES = Paths.get("target", "failures");
    /** The run before this one's failures: one run back, never more. */
    public static final Path PREVIOUS = Paths.get("target", "failures-previous");
    static final Path TRACES = Paths.get("target", "traces");
    private static boolean cleared;
    /**
     * Failures that still leave everything: after these, a run's failures keep their steps, console,
     * network and a screenshot of the window, but no trace or full-page screenshot, the heavy part
     * (site-a.example: 220 failures left 2.7 GB). {@code -DfullEvidence=50} keeps more.
     */
    private static final java.util.concurrent.atomic.AtomicInteger FULL_LEFT =
            new java.util.concurrent.atomic.AtomicInteger(Integer.getInteger("fullEvidence", 10));

    private final BrowserContext context;
    private final Page page;
    private final String testClass;
    private final String testName;
    private final String displayName;
    /** "try-1" while it saves a retried test's first try (G-135): beside the second's, which keeps it. */
    private String tried = "";
    /** The page's scripts that did not load (ads aside), and why: a page that draws itself with one stays blank. */
    private final List<String> failedScripts = java.util.Collections.synchronizedList(new ArrayList<>());
    private final String trace = System.getProperty("trace", "on-failure");
    private final List<String> console = Collections.synchronizedList(new ArrayList<>());
    private final List<String> network = Collections.synchronizedList(new ArrayList<>());

    /** Starts watching a test: its console, its requests, and a trace. */
    Evidence(BrowserContext context, Page page, String testClass, String testName, String displayName) {
        this.context = context;
        this.page = page;
        this.testClass = testClass;
        this.testName = testName;
        this.displayName = displayName;
        startClean();
        context.onConsoleMessage(m -> {
            if ("error".equals(m.type()) || "warning".equals(m.type())) console.add(m.type() + ": " + m.text());
        });
        page.onPageError(error -> console.add("uncaught: " + error));
        context.onRequestFailed(r -> {
            network.add("FAILED " + r.method() + " " + r.url() + " (" + r.failure() + ")");
            if ("script".equals(r.resourceType()) && !Ads.isAd(r.url())) scriptFailed(r.url(), r.failure());
        });
        context.onResponse(r -> {
            if (r.status() < 400) return;
            network.add(r.status() + " " + r.url());
            if ("script".equals(r.request().resourceType()) && !Ads.isAd(r.url())) scriptFailed(r.url(), "answered " + r.status());
        });
        if (!"off".equals(trace)) {
            context.tracing().start(new Tracing.StartOptions().setScreenshots(true).setSnapshots(true));
        }
    }

    /** A test that passed keeps nothing, unless -Dtrace=always. */
    void passed() {
        if ("off".equals(trace)) return;
        try {
            if ("always".equals(trace)) {
                Path dir = Files.createDirectories(TRACES.resolve(testClass));
                context.tracing().stop(new Tracing.StopOptions().setPath(dir.resolve(testName + ".zip")));
            } else {
                context.tracing().stop();
            }
        } catch (RuntimeException | IOException e) {
            // tracing is a help, never a reason to fail
        }
    }

    /** Saves what a failed test leaves behind (all of it for a run's first failures), and returns the folder. */
    Path failed(Throwable cause, String browserVersion) {
        return failed(cause, browserVersion, FULL_LEFT.getAndDecrement() > 0);
    }

    /** Saves what a failed test leaves behind; {@code full}: the trace and a full-page screenshot too. */
    Path failed(Throwable cause, String browserVersion, boolean full) {
        Path dir = tried.isEmpty() ? FAILURES.resolve(testClass).resolve(testName) : FAILURES.resolve(testClass).resolve(testName).resolve(tried);
        try {
            clearKeeping(dir, FIRST_TRY);
            Files.createDirectories(dir);
        } catch (IOException e) {
            return dir;
        }
        attempt(() -> page.screenshot(new Page.ScreenshotOptions().setPath(dir.resolve("screenshot.png")).setFullPage(full)));
        attempt(() -> write(dir.resolve("page.html"), page.content()));
        if (!"off".equals(trace)) {
            attempt(() -> context.tracing().stop(full ? new Tracing.StopOptions().setPath(dir.resolve("trace.zip")) : new Tracing.StopOptions()));
        }
        if (!full) {
            attempt(() -> write(dir.resolve("LIGHT.txt"), "This run already kept the full evidence of its first failures, so this one has no trace.zip\n"
                    + "and its screenshot shows the window, not the whole page. -DfullEvidence=50 keeps more; rerun just\n"
                    + "this test (mvn test -Dtest=Class#method) for all of it.\n"));
        }
        attempt(() -> write(dir.resolve("console.txt"), lines(console, "No console errors or warnings.")));
        attempt(() -> write(dir.resolve("network.txt"), lines(network, "No failed requests.")));
        attempt(() -> write(dir.resolve("steps.txt"), steps(cause)));
        attempt(() -> write(dir.resolve("run.txt"), String.join("\n",
                "Test:     " + testClass + " / " + displayName,
                "Site:     " + SiteConfig.baseUrl(),
                "Browser:  " + System.getProperty("browser", "chromium") + " " + browserVersion
                        + (Boolean.parseBoolean(System.getProperty("headed", "false")) ? ", headed" : ", headless"),
                "Ads:      " + (Boolean.parseBoolean(System.getProperty("blockAds", "true")) ? "blocked" : "allowed"),
                "When:     " + Instant.now(),
                "Java:     " + System.getProperty("java.version") + " on " + System.getProperty("os.name"),
                "Suite:    see crawl/manifest.json for the Suite Builder version and crawl it came from",
                "")));
        return dir;
    }

    private String steps(Throwable cause) {
        StringBuilder out = new StringBuilder(displayName).append("\n\n");
        List<String> steps = StepLog.steps();
        for (int i = 0; i < steps.size(); i++) {
            out.append(i + 1).append(". ").append(steps.get(i)).append(i == steps.size() - 1 ? "   <- FAILED HERE" : "").append("\n");
        }
        out.append("\nBecause: ").append(cause).append("\n");
        String scripts = scriptNote();
        if (scripts != null) out.append(scripts.trim()).append("\n");
        try {
            out.append("URL:     ").append(page.url()).append("\n").append("Title:   ").append(page.title()).append("\n");
        } catch (RuntimeException e) {
            out.append("(the page could not be asked for its URL and title)\n");
        }
        return out.toString();
    }

    private static String lines(List<String> lines, String none) {
        synchronized (lines) {
            return lines.isEmpty() ? none + "\n" : String.join("\n", lines) + "\n";
        }
    }

    private static void write(Path file, String text) throws IOException {
        Files.writeString(file, text, StandardCharsets.UTF_8);
    }

    /**
     * Once per run, before the first test: the last run's failures move to failures-previous/
     * (replacing the run before that), and traces kept by an earlier run are removed.
     * A test that passes now has no folder in failures/.
     */
    private static synchronized void startClean() {
        if (cleared) return;
        cleared = true;
        try {
            deleteAll(TRACES);
            deleteAll(PREVIOUS);
            if (Files.exists(FAILURES)) Files.move(FAILURES, PREVIOUS);
        } catch (IOException e) {
            // A file held open (an editor showing a screenshot, say) can stop the move: clear instead.
            try {
                deleteAll(FAILURES);
            } catch (IOException ignored) {
                // an old folder left over is harmless
            }
        }
    }

    /** A script of the page's that did not load, and why: the first reason given for an address is kept. */
    void scriptFailed(String url, String why) {
        synchronized (failedScripts) {
            for (String seen : failedScripts) if (seen.startsWith(url + " (")) return;
            failedScripts.add(url + " (" + why + ")");
        }
    }

    /**
     * Which of the page's scripts did not load, as a line under the failure, or null: a page drawn by
     * its script stays blank without it, and then fails as "not visible", which hides the reason.
     */
    String scriptNote() {
        synchronized (failedScripts) {
            if (failedScripts.isEmpty()) return null;
            int n = failedScripts.size();
            return "   note: " + (n == 1 ? "a script of the page's" : n + " scripts of the page's") + " did not load, which can leave it blank or half drawn: "
                    + String.join("; ", failedScripts.subList(0, Math.min(3, n))) + (n > 3 ? "; and " + (n - 3) + " more (network.txt, console.txt)" : "");
        }
    }

    /** The folder a retried test's first try is saved in, inside the test's own (G-135). */
    static final String FIRST_TRY = "try-1";

    /** This evidence, saved as a retried test's first try (try-1/), which its second try's keeps. */
    Evidence firstTry() {
        tried = FIRST_TRY;
        return this;
    }

    /** Empties the folder, all but the one named. */
    private static void clearKeeping(Path dir, String keep) throws IOException {
        if (!Files.isDirectory(dir)) return;
        try (Stream<Path> inside = Files.list(dir)) {
            for (Path p : inside.toList()) if (!p.getFileName().toString().equals(keep)) deleteAll(p);
        }
    }

    static void deleteAll(Path dir) throws IOException {
        if (!Files.exists(dir)) return;
        try (Stream<Path> paths = Files.walk(dir)) {
            for (Path p : paths.sorted(Comparator.reverseOrder()).toList()) Files.delete(p);
        }
    }

    private interface Step {
        void run() throws Exception;
    }

    private static void attempt(Step step) {
        try {
            step.run();
        } catch (Exception e) {
            // saving evidence never hides the failure itself
        }
    }

    // ==== YOURS (extras): safe to edit; regenerating keeps what is between these lines ====
    // More this site needs saved when a test fails (the browser's local storage, say).
    // ==== END YOURS (extras) ====
}
